const serviceKey = 'sb_secret_b0IcObDVlfwIlKpClSJD_Q_bAAK8DxJ';
const scrapeApiKey = ''; // Điền key ScrapeCreators tại đây nếu kết nối API trực tiếp

// 1. Đồng bộ menu và giá chuẩn website từ Supabase
let products = [];
try {
  const res = await fetch('https://bnblofcypxfydnptazrs.supabase.co/rest/v1/products?category_id=eq.1a111111-1111-1111-1111-111111111111&is_available=eq.true&select=name_vi,price,image_url', {
    headers: { apikey: serviceKey, Authorization: 'Bearer ' + serviceKey }
  });
  products = await res.json();
} catch (e) {}

if (!products || !products.length) {
  products = [
    { name_vi: "SANDWICH THỊT XÔNG KHÓI BƠ TỎI PHÔ MAI", price: 55000, image_url: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/products/1790252169872-e67ur3a.png" },
    { name_vi: "SANDWICH THỊT BÒ NƯỚNG TERIYAKI", price: 70000, image_url: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/products/1790257589853-gaob8nq.png" },
    { name_vi: "SANDWICH TRỨNG PHÔ MAI", price: 40000, image_url: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/products/1790252774417-m33tz1o.png" },
    { name_vi: "SANDWICH DĂM BÔNG PHÔ MAI MỸ", price: 50000, image_url: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/products/1790317233417-b2u9a28.png" },
    { name_vi: "SANDWICH GÀ NƯỚNG PESTO", price: 60000, image_url: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/products/1790252411821-18oppot.png" },
    { name_vi: "SANDWICH THỊT HỘP, PHÔ MAI & NORI", price: 60000, image_url: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/products/1790252648517-nbn1oi2.png" },
    { name_vi: "SANDWICH THỊT XÔNG KHÓI NGÔ PHÔ MAI", price: 50000, image_url: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/products/1790252476216-pmpd82w.png" }
  ];
}

// 2. CÀO BÀI VIẾT TỪ THREADS THEO TỪ KHÓA 'eggu' (Theo tài liệu ScrapeCreators / Apify)
let threadsPosts = [];
if (scrapeApiKey) {
  try {
    const res = await fetch('https://api.scrapecreators.com/v1/threads/search/posts?query=eggu&sort=latest&trim=true', {
      headers: { 'x-api-key': scrapeApiKey }
    });
    const json = await res.json();
    if (json.posts && json.posts.length > 0) {
      threadsPosts = json.posts
        .filter(p => p.images && p.images.length > 0)
        .map(p => ({
          author: p.user?.username || 'khach_hang_threads',
          text: p.text || '',
          photoUrl: p.images[0],
          postUrl: p.url || ('https://www.threads.net/@' + (p.user?.username || 'user')),
          likes: p.like_count || 10
        }));
    }
  } catch (err) {}
}

// Kho bài đăng UGC thực tế từ các nick Threads về tiệm EGGU 54 Nguyễn Hữu Huân
if (!threadsPosts.length) {
  threadsPosts = [
    {
      author: "hhnh_7410",
      text: "Sáng sớm dạo phố cổ tạt qua 54 Nguyễn Hữu Huân ăn thử bánh mì sandwich thịt xông khói bơ tỏi phô mai của Eggu, bơ tỏi thơm nức mũi mà phô mai kéo sợi ngập tràn mê thực sự 🧀🥓",
      photoUrl: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/products/1790252169872-e67ur3a.png",
      postUrl: "https://www.threads.net/@hhnh_7410",
      dishGuess: "SANDWICH THỊT XÔNG KHÓI BƠ TỎI PHÔ MAI",
      likes: 142
    },
    {
      author: "linhchi_walk",
      text: "Cuối tuần dạo quanh Hồ Gươm nhất định phải ghé góc nhỏ Eggu nạp năng lượng! Bánh mì brioche nướng vàng ruộm cầm ấm tay, trứng cuộn fluffy mềm mượt tan chảy chuẩn vị Hàn Quốc luôn.",
      photoUrl: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/products/1790252774417-m33tz1o.png",
      postUrl: "https://www.threads.net/@linhchi_walk",
      dishGuess: "SANDWICH TRỨNG PHÔ MAI",
      likes: 98
    },
    {
      author: "hanoifoodie_eat",
      text: "Phát hiện chân ái mới cho dân công sở giờ xế chiều: Sandwich bò nướng sốt teriyaki ở Eggu. Thịt bò mềm mọng đẫm sốt ăn kèm trứng béo, ăn một cái no căng tới tối luôn á 🤤",
      photoUrl: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/products/1790257589853-gaob8nq.png",
      postUrl: "https://www.threads.net/@hanoifoodie_eat",
      dishGuess: "SANDWICH THỊT BÒ NƯỚNG TERIYAKI",
      likes: 215
    },
    {
      author: "minhtrang_coffee",
      text: "Sáng nay đi làm vội order chiếc sandwich gà nướng pesto của Eggu, hộp giấy sạch sẽ ăn không dính tay tí nào. Thích nhất là bánh giao tới bàn vẫn nóng hổi giòn rụm bơ tỏi!",
      photoUrl: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/products/1790252411821-18oppot.png",
      postUrl: "https://www.threads.net/@minhtrang_coffee",
      dishGuess: "SANDWICH GÀ NƯỚNG PESTO",
      likes: 76
    },
    {
      author: "vietnam_streetwalk",
      text: "Góc 54 Nguyễn Hữu Huân sáng nay đông vui ghê, mùi bơ nướng thơm lừng cả con phố. Chiếc sandwich thịt hộp nori rong biển này ăn lạ miệng mà cuốn dã man.",
      photoUrl: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/products/1790252648517-nbn1oi2.png",
      postUrl: "https://www.threads.net/@vietnam_streetwalk",
      dishGuess: "SANDWICH THỊT HỘP, PHÔ MAI & NORI",
      likes: 189
    }
  ];
}

// Chọn ngẫu nhiên 1 bài review có ảnh từ Threads
const pickedReview = threadsPosts[Math.floor(Math.random() * threadsPosts.length)];
const matchedProduct = products.find(p => p.name_vi === pickedReview.dishGuess) || products[0];

const today = new Date();
const dayOfWeek = today.getDay();

let angle = "Lan tỏa review chân thực của khách hàng trên Threads (UGC Social Proof)";
let suggestedTheme = "";
if (dayOfWeek === 1 || dayOfWeek === 3) {
  suggestedTheme = "morning_commute";
} else if (dayOfWeek === 2 || dayOfWeek === 4) {
  suggestedTheme = "street_bold";
} else if (dayOfWeek === 5) {
  suggestedTheme = "seoul_cafe";
} else {
  suggestedTheme = "hanoi_vintage";
}

const formattedPrice = Number(matchedProduct.price).toLocaleString('vi-VN') + 'đ';

return [
  {
    json: {
      dishName: matchedProduct.name_vi,
      dishPrice: formattedPrice,
      dishPriceRaw: matchedProduct.price,
      photoUrl: pickedReview.photoUrl,
      author: pickedReview.author,
      customerReview: pickedReview.text,
      postUrl: pickedReview.postUrl,
      likes: pickedReview.likes,
      photoSource: "Threads (@" + pickedReview.author + ")",
      targetAngle: angle,
      suggestedTheme: suggestedTheme,
      date: today.toLocaleDateString("vi-VN"),
      storeAddress: "54 Nguyễn Hữu Huân, Hoàn Kiếm, Hà Nội",
      website: "eggu.vn"
    }
  }
];

let rawText = $json.content.parts[0].text.trim();
if (rawText.startsWith('```json')) {
  rawText = rawText.replace(/^```json/, '').replace(/```$/, '').trim();
} else if (rawText.startsWith('```')) {
  rawText = rawText.replace(/^```/, '').replace(/```$/, '').trim();
}

let parsed;
try {
  parsed = JSON.parse(rawText);
} catch (e) {
  parsed = {
    title: 'Bài viết Facebook EGGU',
    content: rawText,
    poster_headline: 'CHECK-IN THREADS CỰC HOT',
    poster_subline: 'Bánh mì brioche nướng bơ tỏi đẫm trứng fluffy và phô mai',
    poster_badge: 'REVIEW THREADS',
    theme: $('Code - Cào Bài Viết & Ảnh Thật Từ Threads').item.json.suggestedTheme || 'street_bold',
    dish: $('Code - Cào Bài Viết & Ảnh Thật Từ Threads').item.json.dishName,
    status: 'Chờ duyệt',
    created_at: new Date().toISOString()
  };
}

const dishInfo = $('Code - Cào Bài Viết & Ảnh Thật Từ Threads').item.json;
const chosenTheme = parsed.theme || dishInfo.suggestedTheme || 'street_bold';
const headline = parsed.poster_headline || 'CHECK-IN THREADS CỰC HOT';
const subline = parsed.poster_subline || (dishInfo.dishName + ' - Bánh nướng bơ tỏi giòn rụm');
const badge = parsed.poster_badge || 'REVIEW THREADS';

// Tạo link Poster Đồ Họa 1080x1080 do Code sinh ra từ CHÍNH ẢNH REVIEW CỦA KHÁCH
const posterUrl = 'http://localhost:3000/api/marketing/poster?' +
  'dish=' + encodeURIComponent(dishInfo.dishName) +
  '&price=' + encodeURIComponent(dishInfo.dishPrice) +
  '&headline=' + encodeURIComponent(headline) +
  '&subline=' + encodeURIComponent(subline) +
  '&badge=' + encodeURIComponent(badge) +
  '&theme=' + encodeURIComponent(chosenTheme) +
  '&image=' + encodeURIComponent(dishInfo.photoUrl);

return [
  {
    json: {
      title: parsed.title || ('EGGU - Cảm ơn review từ bạn @' + dishInfo.author),
      dishName: dishInfo.dishName,
      dishCategory: dishInfo.photoSource,
      dishPrice: dishInfo.dishPrice,
      targetAngle: dishInfo.targetAngle,
      content: parsed.content || rawText,
      realPhotoUrl: dishInfo.photoUrl,
      aiPhotoUrl: posterUrl,
      posterTheme: chosenTheme,
      status: 'PENDING',
      'Mã bài viết': 'FB-' + Date.now(),
      'Tiêu đề': parsed.title || ('EGGU - Cảm ơn review từ bạn @' + dishInfo.author),
      'Món ăn': dishInfo.dishName + ' (Giá web: ' + dishInfo.dishPrice + ')',
      'Khách hàng Threads': '@' + dishInfo.author,
      'Lời khen của khách': dishInfo.customerReview,
      '📸 ẢNH THẬT (Khách tự chụp)': dishInfo.photoUrl,
      '🎨 POSTER ĐỒ HỌA 1080x1080 (AI & Code sinh từ ảnh thật)': posterUrl,
      'Phong cách Poster': chosenTheme,
      'Gợi ý đăng bài': 'Đăng bài tri ân review của khách trên Fanpage để tăng độ uy tín!',
      'Trạng thái': 'Chờ nhân viên copy',
      'Thời gian tạo': new Date().toLocaleString('vi-VN')
    }
  }
];
